//! Markup metadata of the types of this crate, declared apart from the
//! types themselves: the enumerations and the `markup` part of the classes
//! (`enums.rs` and `classes.rs`, generated by
//! `scripts/generate_markup_types.py`), and, written by hand, the
//! converters, the palettes and their contract, the colour helper and the
//! list of palette colours.

use ferroui_base::data::core::ValueTypes;
use ferroui_base::metadata::MarkupType;

mod classes;
mod converters;
mod enums;
mod palettes;

/// The lists of the types declared in this module, by area.
const TYPE_LISTS: &[&[&MarkupType]] = &[enums::TYPES, classes::TYPES, converters::TYPES, palettes::TYPES];

/// Adds the types declared in this module to the process-wide table of
/// types with markup metadata. Called once by `register_types()`.
pub(crate) fn register() {
    for types in TYPE_LISTS {
        MarkupType::register_all(types);
    }
    ValueTypes::register_global(register_value_types);
    palettes::PaletteColorList::register();
}

/// Registers what the untyped value conversions need to know about the
/// types declared in this module.
fn register_value_types() {
    enums::register_value_types();
    classes::register_value_types();
    converters::register_value_types();
    palettes::register_value_types();
}

